import{_ as t,g as a,e as r,a4 as n}from"./chunks/framework.CEYJDsBW.js";const f=JSON.parse('{"title":"SmartBlockPlacerFindPointerEvent","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/26.1/events/smart-block-placer-find-pointer-event.md","filePath":"en/anvilcraft/26.1/events/smart-block-placer-find-pointer-event.md"}'),o={name:"en/anvilcraft/26.1/events/smart-block-placer-find-pointer-event.md"};function c(i,e,d,l,s,v){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="smartblockplacerfindpointerevent" tabindex="-1">SmartBlockPlacerFindPointerEvent <a class="header-anchor" href="#smartblockplacerfindpointerevent" aria-label="Permalink to &quot;SmartBlockPlacerFindPointerEvent&quot;">​</a></h1><p>When the placer needs to find the next block in an add-on inventory or custom target, provide an <code>ITargetPointer</code> via <code>setPointer(...)</code>. The server first tries reusing an old pointer that is still valid and matches <code>requiredState</code>, posting a new query only when reuse fails. <code>getSourcePos()</code>, <code>getFacing()</code>, operation mode, target mode, and execution phase together determine where to search; <code>requiredState</code> may be null.</p><p>If canceled after posting, the lookup immediately returns <code>null</code>, even if a pointer was already set. When not canceled, the final pointer is read directly, returning <code>null</code> if none was provided. Built-in providers run at <code>LOWEST</code> priority and may overwrite an already-set pointer, so arrange matching conditions and listener order explicitly for custom targets. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/SmartBlockPlacerBlockEntity.java" target="_blank" rel="noreferrer">Query &amp; result reading</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/event/SmartBlockPlacerEventListener.java" target="_blank" rel="noreferrer">Built-in candidates</a></p><table tabindex="0"><thead><tr><th>Event Type</th><th>Construction Site</th></tr></thead><tbody><tr><td><code>SmartBlockPlacerFindPointerEvent</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/entity/SmartBlockPlacerBlockEntity.java#L284" target="_blank" rel="noreferrer"><code>SmartBlockPlacerBlockEntity:284</code></a></td></tr></tbody></table>',4)])])}const m=t(o,[["render",c]]);export{f as __pageData,m as default};
